'use client'

import { IconPlaceholder } from '@/registry/icons/icon-placeholder'
import type { ReactNode } from 'react'

import { cn } from '@/lib/utils'

interface PipelineStage {
  expectedDays?: number
  id: string
  label: string
  /** Chance that an item in this stage closes, 0–1. */
  probability?: number
}

interface PipelineItem {
  enteredStageAt: Date
  id: string
  owner?: string
  stage: string
  subtitle?: string
  title: string
  value?: number
}

interface StageSummary extends PipelineStage {
  count: number
  stuck: number
  value: number
  weighted: number
}

const DAY = 86_400_000

function getDaysInStage(date: Date, now: Date) {
  return Math.max(0, Math.floor((now.getTime() - date.getTime()) / DAY))
}

function isStuck(days: number, expectedDays?: number) {
  return expectedDays !== undefined && days > expectedDays
}

function getStageSummaries(
  stages: PipelineStage[],
  items: PipelineItem[],
  now: Date,
): StageSummary[] {
  return stages.map((stage) => {
    const inStage = items.filter((item) => item.stage === stage.id)
    const value = inStage.reduce((sum, item) => sum + (item.value ?? 0), 0)
    return {
      ...stage,
      count: inStage.length,
      stuck: inStage.filter((item) =>
        isStuck(getDaysInStage(item.enteredStageAt, now), stage.expectedDays),
      ).length,
      value,
      weighted: value * (stage.probability ?? 0),
    }
  })
}

function getStageColor(index: number, count: number) {
  const share = count > 1 ? index / (count - 1) : 1
  return `color-mix(in oklab, var(--chart-2) ${Math.round(50 + share * 50)}%, var(--card))`
}

// Set both fraction digit limits: engines disagree on the default minimum for compact currency, which would render "$42K" on the server and "$42.0K" in the browser.
const compactCurrency = new Intl.NumberFormat('en-US', {
  currency: 'USD',
  maximumFractionDigits: 1,
  minimumFractionDigits: 0,
  notation: 'compact',
  style: 'currency',
})

const fullCurrency = new Intl.NumberFormat('en-US', {
  currency: 'USD',
  maximumFractionDigits: 0,
  minimumFractionDigits: 0,
  style: 'currency',
})

function formatCurrency(value: number, { compact = true } = {}) {
  return (compact ? compactCurrency : fullCurrency).format(value)
}

function formatAge(days: number, style: 'short' | 'long' = 'short') {
  const [amount, unit] =
    days < 28
      ? [days, 'd']
      : days < 90
        ? [Math.floor(days / 7), 'w']
        : [Math.floor(days / 30), 'mo']
  if (style === 'short') return `${amount}${unit}`
  const word = unit === 'd' ? 'day' : unit === 'w' ? 'week' : 'month'
  return `${amount} ${word}${amount === 1 ? '' : 's'}`
}

function PipelineAge({
  className,
  days,
  expectedDays,
}: {
  className?: string
  days: number
  expectedDays?: number
}) {
  const stuck = isStuck(days, expectedDays)
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-xs font-medium whitespace-nowrap tabular-nums [&_svg]:size-3.5 [&_svg]:shrink-0',
        stuck
          ? 'bg-amber-500/10 text-amber-800 dark:text-amber-400'
          : 'text-muted-foreground',
        className,
      )}
    >
      {stuck ? (
        <IconPlaceholder
          lucide='ClockAlertIcon'
          tabler='IconClockExclamation'
          hugeicons='TimeQuarterPassIcon'
          phosphor='ClockCountdownIcon'
          remixicon='RiTimerFlashLine'
          aria-hidden
        />
      ) : (
        <IconPlaceholder
          lucide='ClockIcon'
          tabler='IconClock'
          hugeicons='Clock01Icon'
          phosphor='ClockIcon'
          remixicon='RiTimeLine'
          aria-hidden
        />
      )}
      <span aria-hidden>{formatAge(days)}</span>
      <span className='sr-only'>
        {formatAge(days, 'long')} in stage
        {stuck && `, over the ${expectedDays}-day limit`}
      </span>
    </span>
  )
}

function getInitials(name: string) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('')
}

function PipelineOwner({
  className,
  name,
  showName = false,
}: {
  className?: string
  name: string
  showName?: boolean
}) {
  return (
    <span className={cn('inline-flex min-w-0 items-center gap-2', className)}>
      <span
        aria-hidden
        title={name}
        className='bg-muted text-foreground flex size-6 shrink-0 items-center justify-center rounded-full text-[10px] font-medium'
      >
        {getInitials(name)}
      </span>
      <span className={cn(showName ? 'truncate text-sm' : 'sr-only')}>
        {showName ? name : `Owner: ${name}`}
      </span>
    </span>
  )
}

function PipelineStageHeader({
  className,
  color,
  count,
  id,
  label,
  total,
}: {
  className?: string
  color: string
  count: number
  /** Lets the column's list point at the heading with `aria-labelledby`. */
  id?: string
  label: string
  total?: string
}) {
  return (
    <div className={cn('flex flex-col gap-0.5', className)}>
      <h3 id={id} className='flex items-center gap-2 text-sm font-medium'>
        <span
          aria-hidden
          className='size-2.5 shrink-0 rounded-full'
          style={{ backgroundColor: color }}
        />
        <span className='truncate'>{label}</span>
        <span className='bg-muted text-foreground ml-auto rounded-full px-2 py-0.5 text-xs tabular-nums'>
          {count}
          <span className='sr-only'> {count === 1 ? 'item' : 'items'}</span>
        </span>
      </h3>
      {total !== undefined && (
        <p className='text-muted-foreground pl-4.5 text-xs tabular-nums'>
          <span className='sr-only'>Total </span>
          {total}
        </p>
      )}
    </div>
  )
}

interface PipelineCardProps {
  action?: ReactNode
  className?: string
  days: number
  expectedDays?: number
  owner?: string
  subtitle?: string
  title: string
  value?: string
}

function PipelineCard({
  action,
  className,
  days,
  expectedDays,
  owner,
  subtitle,
  title,
  value,
}: PipelineCardProps) {
  return (
    <div
      className={cn(
        'bg-card flex flex-col gap-3 rounded-lg p-3 shadow-xs ring-1 ring-foreground/10',
        className,
      )}
    >
      <div className='flex items-start justify-between gap-2'>
        <div className='flex min-w-0 flex-col gap-0.5'>
          <p className='text-sm leading-snug font-medium'>{title}</p>
          {subtitle && <p className='text-muted-foreground text-xs'>{subtitle}</p>}
        </div>
        {action && <div className='-mt-1 -mr-1 shrink-0'>{action}</div>}
      </div>
      <div className='flex items-center gap-2'>
        {value !== undefined && (
          <span className='text-sm font-medium tabular-nums'>{value}</span>
        )}
        <PipelineAge className='ml-auto' days={days} expectedDays={expectedDays} />
        {owner && <PipelineOwner name={owner} />}
      </div>
    </div>
  )
}

export {
  PipelineAge,
  PipelineCard,
  PipelineOwner,
  PipelineStageHeader,
  formatAge,
  formatCurrency,
  getDaysInStage,
  getStageColor,
  getStageSummaries,
  isStuck,
}

export type { PipelineCardProps, PipelineItem, PipelineStage, StageSummary }
